71:     if ([string]::IsNullOrWhiteSpace($AgentName)) { return 'ClaudeCode' }
72: 
73:     switch (($AgentName.Trim().ToLowerInvariant() -replace '[^a-z0-9]', '')) {
74:         'claude'       { return 'ClaudeCode' }
