3032: function Invoke-ReplMethodCore {
3033:     [CmdletBinding()]
3034:     param(
3035:         [Parameter(Mandatory)][string]$Method,
3036:         [string]$ParamsYaml = ''
3037:     )
3038: 
3039:     # Local plugin-shim verbs: record the boolean outcome on the script-scoped
3040:     # success flag (so the script-entry exit code is truthful) and return without
3041:     # emitting the boolean to stdout. Emitting it leaked "True" lines, and leaving
3042:     # the flag unset made the script-entry exit 1 even on a successful persist.
3043:     switch -Wildcard ($Method) {
3044:         'workflow.sessionlog.beginTurn'       { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowBeginTurn -ParamsYaml $ParamsYaml); return }
3045:         'workflow.sessionlog.openSession'     { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowOpenSession -ParamsYaml $ParamsYaml); return }
3046:         'workflow.sessionlog.updateTurn'      { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowUpdateTurn -ParamsYaml $ParamsYaml); return }
3047:         'workflow.sessionlog.appendActions'   { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowAppendActions -ParamsYaml $ParamsYaml); return }
3048:         'workflow.sessionlog.appendDialog'    { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowAppendDialog -ParamsYaml $ParamsYaml); return }
3049:         'workflow.sessionlog.completeTurn'    { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowCompleteTurn -ParamsYaml $ParamsYaml); return }
3050:         'workflow.sessionlog.failTurn'        { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowFailTurn -ParamsYaml $ParamsYaml); return }
3051:         'workflow.sessionlog.setTurnTitle'    { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowSetTurnTitle -ParamsYaml $ParamsYaml); return }
3052:         'workflow.sessionlog.setSessionTitle' { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowSetSessionTitle -ParamsYaml $ParamsYaml); return }
3053:         'workflow.failsafe.drain' {
3054:             # These two verbs report a YAML document to stdout as well as a boolean
3055:             # outcome, so they return a result object instead of a bare boolean.
3056:             $drainResult = Invoke-WorkflowFailsafeDrain -ParamsYaml $ParamsYaml
3057:             $script:LastInvokeReplMethodSuccess = [bool]$drainResult.Success
3058:             $drainResult.Output
3059:             return
3060:         }
3061:         'workflow.failsafe.status' {
3062:             $failsafeStatusResult = Invoke-WorkflowFailsafeStatus -ParamsYaml $ParamsYaml
3063:             $script:LastInvokeReplMethodSuccess = [bool]$failsafeStatusResult.Success
3064:             $failsafeStatusResult.Output
3065:             return
3066:         }
3067:     }
3068: 
3069:     $r = Invoke-ReplRaw -Method $Method -ParamsYaml $ParamsYaml
3070:     if ($r.Output) {
3071:         $script:LastInvokeReplMethodSuccess = [bool]$r.Success
3072:         $r.Output
3073:         return
3074:     }
3075: 
3076:     $script:LastInvokeReplMethodSuccess = [bool]$r.Success
3077:     return [bool]$r.Success
3078: }
