3080: function Invoke-ReplMethod {
3081:     <#
3082:     .SYNOPSIS
3083:     Dispatches a method and emits one typed envelope for local session mutations.
3084:     .DESCRIPTION
3085:     Keeps boolean control flow internal. Diagnostics remain on stderr, while stdout
3086:     carries the same persisted/queued/rejected/lost/unchanged receipt as the cache.
3087:     #>
3088:     [CmdletBinding()]
3089:     param(
3090:         [Parameter(Mandatory)][string]$Method,
3091:         [string]$ParamsYaml = ''
3092:     )
3093:     $localMethods = @(
3094:         'workflow.sessionlog.beginTurn', 'workflow.sessionlog.openSession',
3095:         'workflow.sessionlog.updateTurn', 'workflow.sessionlog.appendActions',
3096:         'workflow.sessionlog.appendDialog', 'workflow.sessionlog.completeTurn',
3097:         'workflow.sessionlog.failTurn', 'workflow.sessionlog.setTurnTitle',
3098:         'workflow.sessionlog.setSessionTitle'
3099:     )
3100:     if ($Method -notin $localMethods) {
3101:         Invoke-ReplMethodCore -Method $Method -ParamsYaml $ParamsYaml
3102:         return
3103:     }
3104: 
3105:     $script:LastReplPersistenceDetails = $null
3106:     $script:LastInvokeReplMethodSuccess = $false
3107:     try {
3108:         Invoke-ReplMethodCore -Method $Method -ParamsYaml $ParamsYaml | Out-Null
3109:     } catch {
3110:         $script:LastInvokeReplMethodSuccess = $false
3111:         $message = "$Method failed: $_"
3112:         if (-not $script:LastReplPersistenceDetails -or $script:LastReplPersistenceDetails.code -notin @('rejected', 'lost')) {
3113:             [void](Publish-ReplSessionVerbReceipt -Receipt (New-ReplSessionVerbReceipt -Disposition rejected -Method $Method -Message $message -ChildStderr $message))
3114:         }
3115:         [Console]::Error.WriteLine($message)
3116:     }
3117:     if (-not $script:LastReplPersistenceDetails) {
3118:         $disposition = if ($script:LastInvokeReplMethodSuccess) { 'unchanged' } else { 'rejected' }
3119:         $requestId = if ($Method -in @('workflow.sessionlog.openSession', 'workflow.sessionlog.setSessionTitle')) { '' } else { Get-ReplTurnCacheField -Field 'turnRequestId' }
3120:         [void](Publish-ReplSessionVerbReceipt -Receipt (New-ReplSessionVerbReceipt -Disposition $disposition -Method $Method -RequestId $requestId -Message "$Method completed without a remote persistence receipt."))
3121:     }
3122:     if (-not $script:LastInvokeReplMethodSuccess -and $script:LastReplPersistenceDetails.code -in @('persisted', 'queued', 'unchanged')) {
3123:         $prior = $script:LastReplPersistenceDetails
3124:         [void](Publish-ReplSessionVerbReceipt -Receipt (New-ReplSessionVerbReceipt -Disposition rejected -Method $Method -RequestId ([string]$prior.requestId) -FailsafePath ([string]$prior.failsafePath) -Message "$Method failed after an earlier substep; the overall operation was not confirmed."))
3125:     }
3126:     $receipt = $script:LastReplPersistenceDetails
3127:     $receipt['method'] = $Method
3128:     $script:LastInvokeReplMethodSuccess = ($receipt.code -in @('persisted', 'queued', 'unchanged'))
3129:     $envelope = [ordered]@{ type = 'result'; payload = [ordered]@{ result = $receipt } }
3130:     ConvertTo-Yaml -Data $envelope -Options WithIndentedSequences
3131: }
3132: 
3133: # Script-entry: only when invoked directly with -Method (not when dot-sourced).
3134: if ($Method -and $MyInvocation.InvocationName -ne '.') {
3135:     $script:LastInvokeReplMethodSuccess = $false
3136:     Invoke-ReplMethod -Method $Method -ParamsYaml $ParamsYaml
3137:     if (-not $script:LastInvokeReplMethodSuccess) { exit 1 }
3138:     exit 0
3139: }

